/* ============================================
   GreenBean Coffee — Design System
   ============================================ */

/* --- CSS Custom Properties --- */
:root {
  --color-primary: #00824A;
  --color-primary-hover: #006B3D;
  --color-primary-light: #E6F4EE;
  --color-dark: #32462F;
  --color-dark-light: #4A6346;
  --color-cream: #F3CEA1;
  --color-cream-light: #FDF2E4;
  --color-cream-dark: #D4A76A;
  --color-brown: #6B4C3B;
  --color-brown-light: #8B6F5E;
  --color-white: #FFFFFF;
  --color-off-white: #FFFDF7;
  --color-gray-50: #FAFAF9;
  --color-gray-100: #F5F0EB;
  --color-gray-200: #E8E0D5;
  --color-gray-300: #D4C9BC;
  --color-gray-400: #A89B8C;
  --color-gray-500: #7A6E62;
  --color-gray-600: #5C5248;
  --color-gray-700: #3D362F;
  --color-gray-800: #2D2722;
  --color-gray-900: #1A1714;

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-display: 'DM Serif Display', Georgia, 'Times New Roman', serif;

  --radius-sm: 0.5rem;
  --radius-md: 0.75rem;
  --radius-lg: 1rem;
  --radius-xl: 1.5rem;

  --shadow-sm: 0 1px 2px rgba(50, 70, 47, 0.06);
  --shadow-md: 0 4px 12px rgba(50, 70, 47, 0.08);
  --shadow-lg: 0 8px 30px rgba(50, 70, 47, 0.12);
  --shadow-xl: 0 16px 48px rgba(50, 70, 47, 0.14);

  --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-base: 250ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 350ms cubic-bezier(0.4, 0, 0.2, 1);

  --max-w-content: 1280px;
}

/* --- Reset & Base --- */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--color-gray-800);
  background-color: var(--color-off-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-display);
  line-height: 1.2;
  color: var(--color-gray-900);
}

.display-lg {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 5vw, 4rem);
  line-height: 1.1;
}

.display-md {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3rem);
  line-height: 1.15;
}

.heading-lg {
  font-family: var(--font-display);
  font-size: clamp(1.75rem, 3vw, 2.25rem);
}

.heading-md {
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 2.5vw, 1.75rem);
}

.heading-sm {
  font-family: var(--font-display);
  font-size: 1.25rem;
}

.body-lg {
  font-size: 1.125rem;
  line-height: 1.7;
}

.body-sm {
  font-size: 0.875rem;
  line-height: 1.6;
}

.text-primary { color: var(--color-primary); }
.text-dark { color: var(--color-dark); }
.text-cream { color: var(--color-cream-dark); }
.text-brown { color: var(--color-brown); }
.text-muted { color: var(--color-gray-500); }

/* --- Layout Utilities --- */
.container {
  width: 100%;
  max-width: var(--max-w-content);
  margin-left: auto;
  margin-right: auto;
  padding-left: 1.5rem;
  padding-right: 1.5rem;
}

.section {
  padding-top: 5rem;
  padding-bottom: 5rem;
}

.section-sm {
  padding-top: 3rem;
  padding-bottom: 3rem;
}

@media (max-width: 768px) {
  .section { padding-top: 3rem; padding-bottom: 3rem; }
  .section-sm { padding-top: 2rem; padding-bottom: 2rem; }
}

/* --- Button System --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-family: var(--font-sans);
  font-weight: 600;
  font-size: 0.9375rem;
  padding: 0.75rem 1.75rem;
  border-radius: var(--radius-lg);
  transition: all var(--transition-fast);
  white-space: nowrap;
  line-height: 1;
  letter-spacing: 0.01em;
}

.btn:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

.btn-primary {
  background-color: var(--color-primary);
  color: var(--color-white);
  box-shadow: 0 2px 8px rgba(0, 130, 74, 0.3);
}

.btn-primary:hover {
  background-color: var(--color-primary-hover);
  box-shadow: 0 4px 16px rgba(0, 130, 74, 0.4);
  transform: translateY(-1px);
}

.btn-primary:active {
  transform: translateY(0);
}

.btn-outline {
  background-color: transparent;
  color: var(--color-primary);
  border: 1.5px solid var(--color-primary);
}

.btn-outline:hover {
  background-color: var(--color-primary-light);
}

.btn-ghost {
  background-color: transparent;
  color: var(--color-gray-700);
}

.btn-ghost:hover {
  background-color: var(--color-gray-100);
}

.btn-cream {
  background-color: var(--color-cream);
  color: var(--color-dark);
  box-shadow: var(--shadow-sm);
}

.btn-cream:hover {
  background-color: var(--color-cream-dark);
  color: var(--color-white);
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

.btn-white {
  background-color: var(--color-white);
  color: var(--color-dark);
  box-shadow: var(--shadow-sm);
}

.btn-white:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

.btn-lg {
  padding: 1rem 2.5rem;
  font-size: 1.0625rem;
  border-radius: var(--radius-xl);
}

.btn-sm {
  padding: 0.5rem 1.25rem;
  font-size: 0.875rem;
  border-radius: var(--radius-md);
}

/* --- Card Component --- */
.card {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-gray-200);
  transition: box-shadow var(--transition-base), transform var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-lg);
}

.card-interactive {
  cursor: pointer;
}

.card-interactive:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

/* --- Badge --- */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 0.25rem 0.75rem;
  border-radius: 9999px;
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.badge-primary {
  background-color: var(--color-primary-light);
  color: var(--color-primary);
}

.badge-cream {
  background-color: var(--color-cream-light);
  color: var(--color-brown);
}

.badge-dark {
  background-color: var(--color-dark);
  color: var(--color-white);
}

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--color-white);
  border-top: 1px solid var(--color-gray-200);
  box-shadow: 0 -4px 20px rgba(0,0,0,0.08);
  z-index: 1000;
  padding: 1.25rem 0;
  transform: translateY(0);
  transition: transform var(--transition-slow), opacity var(--transition-slow);
}

.cookie-banner[aria-hidden="true"] {
  transform: translateY(100%);
  opacity: 0;
  pointer-events: none;
}

/* --- Accordion (Footer Mobile) --- */
.footer-accordion-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 0.75rem 0;
  font-weight: 600;
  color: var(--color-white);
  font-size: 0.9375rem;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.footer-accordion-trigger .icon {
  transition: transform var(--transition-base);
}

.footer-accordion-trigger[aria-expanded="true"] .icon {
  transform: rotate(180deg);
}

.footer-accordion-content {
  overflow: hidden;
  max-height: 0;
  transition: max-height var(--transition-slow);
}

.footer-accordion-content[aria-hidden="false"] {
  max-height: 600px;
}

/* --- Tabs --- */
.tab-list {
  display: flex;
  gap: 0.25rem;
  background: var(--color-gray-100);
  border-radius: var(--radius-xl);
  padding: 0.375rem;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.tab-trigger {
  flex-shrink: 0;
  padding: 0.625rem 1.25rem;
  border-radius: var(--radius-lg);
  font-weight: 500;
  font-size: 0.875rem;
  color: var(--color-gray-500);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.tab-trigger:hover {
  color: var(--color-gray-700);
}

.tab-trigger[aria-selected="true"] {
  background: var(--color-white);
  color: var(--color-dark);
  font-weight: 600;
  box-shadow: var(--shadow-sm);
}

.tab-content {
  display: none;
}

.tab-content[aria-hidden="false"] {
  display: block;
}

/* --- Carousel --- */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  gap: 1rem;
  transition: transform var(--transition-slow);
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 5;
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 50%;
  background: var(--color-white);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-dark);
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  box-shadow: var(--shadow-lg);
  background: var(--color-primary-light);
}

.carousel-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.carousel-btn-prev { left: -0.5rem; }
.carousel-btn-next { right: -0.5rem; }

@media (max-width: 640px) {
  .carousel-btn-prev { left: 0; }
  .carousel-btn-next { right: 0; }
}

/* --- Store Locator Map --- */
.map-container {
  position: relative;
  width: 100%;
  height: 400px;
  background: var(--color-gray-100);
  border-radius: var(--radius-xl);
  overflow: hidden;
}

.map-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #E8E0D5 0%, #D4C9BC 100%);
}

/* --- Toggle Switch --- */
.toggle-group {
  display: inline-flex;
  background: var(--color-gray-100);
  border-radius: var(--radius-lg);
  padding: 0.25rem;
}

.toggle-option {
  padding: 0.625rem 1.5rem;
  border-radius: var(--radius-md);
  font-weight: 500;
  font-size: 0.875rem;
  color: var(--color-gray-500);
  transition: all var(--transition-fast);
}

.toggle-option[aria-pressed="true"] {
  background: var(--color-white);
  color: var(--color-dark);
  font-weight: 600;
  box-shadow: var(--shadow-sm);
}

/* --- Search Input --- */
.search-input-wrap {
  position: relative;
}

.search-input-wrap .search-icon {
  position: absolute;
  left: 1rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--color-gray-400);
  pointer-events: none;
}

.search-input {
  width: 100%;
  padding: 0.875rem 1rem 0.875rem 2.75rem;
  border: 1.5px solid var(--color-gray-200);
  border-radius: var(--radius-xl);
  font-family: var(--font-sans);
  font-size: 0.9375rem;
  background: var(--color-white);
  color: var(--color-gray-800);
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.search-input:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(0, 130, 74, 0.1);
}

.search-input::placeholder {
  color: var(--color-gray-400);
}

/* --- Filter Panel --- */
.filter-panel {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-xl);
  padding: 1.5rem;
  box-shadow: var(--shadow-lg);
  display: none;
}

.filter-panel.open {
  display: block;
}

/* --- Divider --- */
.divider {
  width: 100%;
  height: 1px;
  background: var(--color-gray-200);
}

/* --- Animations --- */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(24px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-fade-in-up {
  animation: fadeInUp 0.5s var(--transition-slow) both;
}

@keyframes scaleIn {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.animate-scale-in {
  animation: scaleIn 0.3s var(--transition-base) both;
}

/* --- Focus visible --- */
:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* --- Skip Link --- */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--color-primary);
  color: var(--color-white);
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-md);
  z-index: 2000;
  font-weight: 600;
}

.skip-link:focus {
  top: 1rem;
}

