.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  gap: 1rem;
  transition: transform var(--transition-slow);
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 5;
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 50%;
  background: var(--color-white);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-dark);
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  box-shadow: var(--shadow-lg);
  background: var(--color-primary-light);
}

.carousel-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.carousel-btn-prev { left: -0.5rem; }
.carousel-btn-next { right: -0.5rem; }

@media (max-width: 640px) {
  .carousel-btn-prev { left: 0; }
  .carousel-btn-next { right: 0; }
}

/* --- Store Locator Map --- */
.map-container {
  position: relative;
  width: 100%;
  height: 400px;
  background: var(--color-gray-100);
  border-radius: var(--radius-xl);
  overflow: hidden;
}

.map-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #E8E0D5 0%, #D4C9BC 100%);
}

/* --- Toggle Switch --- */
.toggle-group {
  display: inline-flex;
  background: var(--color-gray-100);
  border-radius: var(--radius-lg);
  padding: 0.25rem;
}

.toggle-option {
  padding: 0.625rem 1.5rem;
  border-radius: var(--radius-md);
  font-weight: 500;
  font-size: 0.875rem;
  color: var(--color-gray-500);
  transition: all var(--transition-fast);
}

.toggle-option[aria-pressed="true"] {
  background: var(--color-white);
  color: var(--color-dark);
  font-weight: 600;
  box-shadow: var(--shadow-sm);
}

/* --- Search Input --- */
.search-input-wrap {
  position: relative;
}

.search-input-wrap .search-icon {
  position: absolute;
  left: 1rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--color-gray-400);
  pointer-events: none;
}

.search-input {
  width: 100%;
  padding: 0.875rem 1rem 0.875rem 2.75rem;
  border: 1.5px solid var(--color-gray-200);
  border-radius: var(--radius-xl);
  font-family: var(--font-sans);
  font-size: 0.9375rem;
  background: var(--color-white);
  color: var(--color-gray-800);
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.search-input:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(0, 130, 74, 0.1);
}

.search-input::placeholder {
  color: var(--color-gray-400);
}

/* --- Filter Panel --- */
.filter-panel {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-xl);
  padding: 1.5rem;
  box-shadow: var(--shadow-lg);
  display: none;
}

.filter-panel.open {
  display: block;
}

/* --- Divider --- */
.divider {
  width: 100%;
  height: 1px;
  background: var(--color-gray-200);
}

/* --- Animations --- */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(24px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-fade-in-up {
  animation: fadeInUp 0.5s var(--transition-slow) both;
}

@keyframes scaleIn {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.animate-scale-in {
  animation: scaleIn 0.3s var(--transition-base) both;
}

/* --- Focus visible --- */
:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* --- Skip Link --- */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--color-primary);
  color: var(--color-white);
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-md);
  z-index: 2000;
  font-weight: 600;
}

.skip-link:focus {
  top: 1rem;
}

